import numpy as np


def encode(x, W, b):
    return np.tanh(x @ W + b)


def decode(z, W, b):
    return z @ W + b


def reconstruction_loss(x, x_hat):
    return np.mean((x - x_hat) ** 2)


def reparameterize(mu, log_var, eps):
    return mu + np.exp(0.5 * log_var) * eps


def kl_divergence(mu, log_var):
    return -0.5 * np.sum(1 + log_var - mu ** 2 - np.exp(log_var))


def show(label, value):
    print(label, None if value is None else np.round(value, 4))


rng = np.random.default_rng(0)
x = rng.standard_normal((4, 6))                 # 4 samples with 6 features
W_enc, b_enc = rng.standard_normal((6, 2)) * 0.5, np.zeros(2)   # 6 -> 2 bottleneck
W_dec, b_dec = rng.standard_normal((2, 6)) * 0.5, np.zeros(6)   # 2 -> 6 reconstruction

z = encode(x, W_enc, b_enc)
x_hat = decode(z, W_dec, b_dec)
print("latent shape:", np.shape(z), "reconstruction shape:", np.shape(x_hat))
show("reconstruction loss:", reconstruction_loss(x, x_hat))

mu, log_var = np.array([0.0, 1.0]), np.array([0.0, 0.0])
show("sampled z:", reparameterize(mu, log_var, np.array([1.0, -1.0])))
show("KL divergence:", kl_divergence(mu, log_var))
